using ChronoLith.Brocal.Domain.Abstractions;

namespace ChronoLith.Brocal.Domain.Platform;

public enum FileCategory
{
    Other = 0,
    Logo = 1,
    Photo = 2,
    Signature = 3,
    Document = 4,
    Receipt = 5,
    GeneratedPdf = 6,
    InvoiceXml = 7,
    Export = 8
}

/// <summary>
/// Metadata of a file uploaded or generated by a company (photos, signatures, permits, receipts, PDFs).
/// The bytes live in the file storage; the size counts against the storage quota of the company.
/// </summary>
public sealed class StoredFile : TenantAggregateRoot
{
    public const long MaxUploadBytes = 25L * 1024 * 1024;

    private static readonly HashSet<string> AllowedContentTypes = new(StringComparer.OrdinalIgnoreCase)
    {
        "image/jpeg", "image/png", "image/webp", "image/gif", "application/pdf", "application/xml", "text/xml",
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", "application/vnd.ms-excel",
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document", "application/msword",
        "text/csv", "text/plain", "application/zip"
    };

    private StoredFile()
    {
    }

    private StoredFile(Guid id, string fileName, string contentType, long sizeBytes, string sha256, string storageKey, FileCategory category)
        : base(id)
    {
        FileName = fileName;
        ContentType = contentType;
        SizeBytes = sizeBytes;
        Sha256 = sha256;
        StorageKey = storageKey;
        Category = category;
    }

    public string FileName { get; private set; } = null!;

    public string ContentType { get; private set; } = null!;

    public long SizeBytes { get; private set; }

    public string Sha256 { get; private set; } = null!;

    /// <summary>Relative key inside the storage (<c>{tenant}/{yyyy}/{MM}/{id}</c>).</summary>
    public string StorageKey { get; private set; } = null!;

    public FileCategory Category { get; private set; }

    /// <summary>Owner record (<c>ServiceTicket</c>, <c>UnitPermit</c>…), informative.</summary>
    public string? OwnerType { get; private set; }

    public Guid? OwnerId { get; private set; }

    public static bool IsAllowedContentType(string contentType) => AllowedContentTypes.Contains(contentType);

    public static bool IsImage(string contentType) => contentType.StartsWith("image/", StringComparison.OrdinalIgnoreCase);

    public static Result<StoredFile> Create(Guid id, string fileName, string contentType, long sizeBytes, string sha256, string storageKey, FileCategory category)
    {
        if (sizeBytes <= 0 || sizeBytes > MaxUploadBytes)
        {
            return FileErrors.TooLarge;
        }

        if (!IsAllowedContentType(contentType))
        {
            return FileErrors.ContentTypeNotAllowed;
        }

        var name = Path.GetFileName(fileName ?? string.Empty).Trim();
        if (name.Length == 0)
        {
            name = "archivo";
        }

        if (name.Length > 200)
        {
            name = name[^200..];
        }

        return new StoredFile(id, name, contentType.ToLowerInvariant(), sizeBytes, sha256, storageKey, category);
    }

    public void AttachTo(string ownerType, Guid ownerId)
    {
        OwnerType = ownerType;
        OwnerId = ownerId;
    }
}

public static class FileErrors
{
    public static readonly Error NotFound = Error.NotFound("Files.NotFound", "El archivo no existe.");

    public static readonly Error TooLarge = Error.Validation("Files.TooLarge", "El archivo está vacío o supera el máximo de 25 MB.");

    public static readonly Error ContentTypeNotAllowed = Error.Validation(
        "Files.ContentTypeNotAllowed", "Tipo de archivo no permitido. Usa imágenes, PDF, XML, Excel, Word, CSV o ZIP.");

    public static readonly Error InvalidSignature = Error.Forbidden("Files.InvalidSignature", "El enlace del archivo expiró o no es válido.");

    public static readonly Error NotAnImage = Error.Validation("Files.NotAnImage", "El archivo debe ser una imagen.");
}
